// The Rust core for Android: boltffi's JNI bindings (`CoreFfi`, `TunnelFfi`)
// with the native libraries, and the Crux types (`Event`, `Effect`,
// `ViewModel`) the shell exchanges with it in bincode. Everything here is
// generated by `just android-generate`.
plugins {
    alias(libs.plugins.android.library)
}

android {
    namespace = "com.crayen.domovoi.shared"
    compileSdk = 37
    ndkVersion = "29.0.13846066"
    defaultConfig {
        minSdk = 29
    }
    sourceSets.getByName("main").kotlin.srcDir("../shared-types")
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

kotlin {
    jvmToolchain(17)
    compilerOptions {
        optIn.add("kotlin.ExperimentalUnsignedTypes")
        freeCompilerArgs.add("-nowarn")
    }
}
